//! 📞️ Imported calls borrow their actual module, operands and source until a paid typed reply commits.
use super::*;
pub(crate) struct OriginalHostCall{function:u32,start:usize,pc:usize,epoch:u64}
/// 👓️ No host-call name, argument or result type is cloned out of the retained Core.
pub struct CoreOriginalHostCall<'a>{pub module:&'a str,pub name:&'a str,pub arguments:&'a[Value],pub results:&'a[ValueType]}
impl CoreInstanceOpening{
 pub fn original_host_call_pending(&self)->bool{self.host_call.is_some()}
 pub fn original_host_call<'a>(&'a self,module:&'a Arc<CoreModule>,cx:&StepContext<'_>)->Result<Option<CoreOriginalHostCall<'a>>,OriginalTurnFailure>{self.validate(module,cx)?;let Some(call)=self.host_call.as_ref()else{return Ok(None)};if cx.original_source_epoch().is_none_or(|epoch|epoch<call.epoch){return Err(refused("Core host read precedes its actual originating call").into())}let(module_name,name,type_index)=match module.functions.get(call.function as usize){Some(FunctionDecl::Import{module,name,type_index})=>(module.as_str(),name.as_str(),*type_index),_=>return Err(refused("Core host frontier requires its declared actual import").into())};let ty=module.types.get(type_index as usize).ok_or_else(||refused("Core host frontier type is absent"))?;let machine=self.core.as_ref().and_then(|core|core.machine.as_ref()).ok_or_else(||refused("Core host frontier has no actual retained machine"))?;Ok(Some(CoreOriginalHostCall{module:module_name,name,arguments:&machine.values[call.start..],results:&ty.results}))}
 /// 📥️ A typed reply is admitted before replacing any operands or allocating its exact result backing.
 pub fn reply_original_host_step(&mut self,module:&Arc<CoreModule>,results:&[Value],cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(module,cx)?;let call=self.host_call.as_ref().ok_or_else(||refused("Core host reply has no original pending import"))?;if cx.original_source_epoch().is_none_or(|epoch|epoch<call.epoch){return Err(refused("Core host reply precedes its actual request").into())}let ty=module.functions.get(call.function as usize).and_then(|function|module.types.get(function.type_index()as usize)).ok_or_else(||refused("Core host reply type is absent"))?;if results.len()!=ty.results.len()||results.iter().zip(&ty.results).any(|(value,ty)|value.value_type()!=*ty){return Err(refused("Core host reply changes its actual declared result types").into())}if cx.original_retirement_active(){let root=self.core.as_ref().and_then(|core|core.machine.as_ref()).and_then(|machine|machine.frames.first()).map(|frame|frame.function).ok_or_else(||refused("Core cleanup host reply has no actual root"))?;if !retirement_export(module,root)||!matches!(module.functions.get(call.function as usize),Some(FunctionDecl::Import{module,name,..})if module=="semio:framework/pure@1.0.0"&&name=="operation-clock-us"){return Err(refused("Core cleanup cannot resume a semantic host import").into())}}else if cx.is_cancelled(){return Ok(false)}let machine=self.core.as_mut().unwrap().machine.as_mut().unwrap();let target=call.start.checked_add(results.len()).ok_or_else(||refused("Core host result count exceeds native storage"))?;let grow=target>machine.values.capacity();let capacity=if grow{bytes_for::<Value>(target)?}else{0};let release=if grow{bytes_for::<Value>(machine.values.capacity())?}else{0};let copy=bytes_for::<Value>(if grow{target}else{results.len()})?.checked_add(size_of::<OriginalHostCall>()+size_of::<usize>()).ok_or_else(||refused("Core host result copy size overflow"))?;if !charge(cx,copy,capacity,release)?{return Ok(false)}if grow{let mut values=Vec::with_capacity(target);values.extend_from_slice(&machine.values[..call.start]);values.extend_from_slice(results);machine.values=values;}else{machine.values.truncate(call.start);machine.values.extend_from_slice(results);}machine.frames.last_mut().unwrap().pc=call.pc;self.host_call=None;Ok(true)
 }
}
pub(super) fn admit(module:&CoreModule,function:u32,machine:&mut Machine,selector:bool,pc:usize,cx:&mut StepContext<'_>)->Result<Option<OriginalHostCall>,OriginalTurnFailure>{let ty=match module.functions.get(function as usize){Some(FunctionDecl::Import{type_index,..})=>module.types.get(*type_index as usize).ok_or_else(||refused("Core original import type is absent"))?,_=>return Err(refused("Core host admission requires an actual imported function").into())};let available=machine.values.len().checked_sub(usize::from(selector)).ok_or_else(||refused("Core original imported call selector is absent"))?;let start=available.checked_sub(ty.parameters.len()).ok_or_else(||refused("Core original imported call operands are absent"))?;if machine.values[start..available].iter().zip(&ty.parameters).any(|(value,ty)|value.value_type()!=*ty){return Err(refused("Core original imported call arguments change their declared types").into())}let epoch=cx.original_source_epoch().ok_or_else(||refused("Core original imported call has no actual epoch"))?;if !charge(cx,size_of::<OriginalHostCall>()+size_of::<Value>(),0,0)?{return Ok(None)}if selector{machine.values.pop();}Ok(Some(OriginalHostCall{function,start,pc,epoch}))}

#[cfg(test)]
mod tests{
 use super::*;
 use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
 use semio_framework_actor::{RetainedTurnInput,OriginalGuestExecutionBudget};
 use semio_framework_value::RetainedCloneGrant;
 fn clock()->Option<u64>{Some(1000)}
 fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:2_000_000,maximum_capacity_bytes:2_000_000,maximum_release_bytes:2_000_000,maximum_depth:64}}
 fn binary()->Vec<u8>{let mut bytes=b"\0asm\x01\0\0\0".to_vec();for(id,data)in[(1,vec![1,0x60,1,0x7f,1,0x7f]),(2,vec![1,4,b'h',b'o',b's',b't',6,b'd',b'o',b'u',b'b',b'l',b'e',0,0]),(3,vec![1,0]),(7,vec![1,3,b'r',b'u',b'n',0,1]),(10,vec![1,6,0,0x20,0,0x10,0,0x0b])]{bytes.extend([id,data.len()as u8]);bytes.extend(data)}bytes}
 /// 📞️ The imported function crosses the real borrowed frontier; denied, foreign and wrong-shaped replies preserve its paid owner.
 #[test]
 fn original_import_reply_preserves_source_operands_and_matches_independent_vm(){
  let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
  for row in fixture["cases"].as_array().unwrap(){let bytes=binary();let input=row["input"].as_i64().unwrap()as i32;let engine=wasmtime::Engine::default();let oracle=wasmtime::Module::new(&engine,&bytes).unwrap();let mut store=wasmtime::Store::new(&engine,());let function=wasmtime::Func::wrap(&mut store,|value:i32|value.wrapping_mul(2));let instance=wasmtime::Instance::new(&mut store,&oracle,&[function.into()]).unwrap();let expected=instance.get_typed_func::<i32,i32>(&mut store,"run").unwrap().call(&mut store,input).unwrap();assert_eq!(i64::from(expected),row["output"].as_i64().unwrap());let module=Arc::new(CoreModule::parse(&bytes).unwrap());let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(95),Generation(7),stock,clock,1000000,1000000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap().unwrap();for _ in 0..100{if owner.resources_ready(){break}epoch+=1;caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap();}epoch+=1;assert!(caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.begin_function_step(&module,1,&[Value::I32(input)],cx)}).unwrap());
   for _ in 0..20{if owner.original_host_call_pending(){break}epoch+=1;caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;let input=RetainedTurnInput::borrow_original(cx)?;owner.advance_scalar(&module,OriginalGuestExecutionBudget{input,fuel:1,deadline_us:cx.deadline_us()},cx)?.result?;Ok(())}).unwrap();}assert!(owner.original_host_call_pending());epoch+=1;caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;let call=owner.original_host_call(&module,cx)?.unwrap();assert_eq!((call.module,call.name),("host","double"));assert_eq!(call.arguments,&[Value::I32(input)]);assert_eq!(call.results,&[ValueType::I32]);Ok(())}).unwrap();
   epoch+=1;assert!(!caller.turn(RetainedCloneGrant{maximum_copy_bytes:0,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;owner.reply_original_host_step(&module,&[Value::I32(expected)],cx)}).unwrap());let mut foreign=OriginalJobFixtureCaller::admit(OperationId(95),Generation(7),stock,clock,1000000,1000000);assert!(foreign.turn(stock,|cx|{cx.bind_original_source_epoch(epoch+1)?;owner.reply_original_host_step(&module,&[Value::I32(expected)],cx)}).is_err());foreign.retire(stock);epoch+=1;assert!(caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.reply_original_host_step(&module,&[Value::I64(i64::from(expected))],cx)}).is_err());assert!(owner.original_host_call_pending());epoch+=1;assert!(caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.reply_original_host_step(&module,&[Value::I32(expected)],cx)}).unwrap());assert!(!owner.original_host_call_pending());
   for _ in 0..100{epoch+=1;let call=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;let input=RetainedTurnInput::borrow_original(cx)?;owner.advance_scalar(&module,OriginalGuestExecutionBudget{input,fuel:1,deadline_us:cx.deadline_us()},cx)}).unwrap();if call.result.unwrap()==CoreOriginalInvocationStatus::Complete{break}}assert_eq!(owner.invocation_values(),Some(&[Value::I32(expected)][..]));caller.cancel().cancel_now();for _ in 0..100{if owner.terminal_is_empty(){break}epoch+=1;caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.close_step(&module,cx)}).unwrap();}assert!(owner.terminal_is_empty());caller.retire(stock);
  }
 }
}
